// t = { start, dnsEnd, tcpEnd, tlsEnd, reqSent, firstByte, end }
function breakdown(t) {
  return {
    dns:    t.dnsEnd - t.start,
    tcp:    t.tcpEnd - t.start,        // TCP handshake
    tls:    t.tlsEnd - t.start,        // TLS handshake
    origin: t.firstByte - t.reqSent,   // server processing
    total:  t.end - t.start,
  };
}

function slowestPhase(b) {
  // Pick the phase with the largest number.
  return Object.entries(b).sort((a, c) => c[1] - a[1])[0][0];
}
